unsigned int computeChainStages(unsigned int count_, unsigned int stages_param_, double taper_)
{
    if(taper_ <= 0.0)
    {
        return 0;
    }
    if(stages_param_ > 0)
    {
        return stages_param_;
    }
    return std::max((unsigned int)1, (unsigned int)ceil(log((double)count_) / log(taper_)));
}
